function addr(x) {
  if (!x) return '';
  if (typeof x === 'string') {
    const m = x.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    return (m ? m[0] : x).trim();
  }
  if (x.text) return addr(x.text);
  if (Array.isArray(x.value) && x.value[0]) return addr(x.value[0].address || x.value[0]);
  if (x.address) return String(x.address).trim();
  return String(x).trim();
}
function looksLikeApplication(hay) {
  const lower = String(hay || '').toLowerCase();
  const needles = [
    'i am applying', "i'm applying", 'please find my', 'attached cv', 'attached resume',
    'curriculum vitae', ' resume', ' cv ', 'application for',
    'i would like to join', 'i want to intern', 'cover letter'
  ];
  if (needles.some((n) => lower.includes(n))) return true;
  return lower.includes('apply') && (lower.includes('role') || lower.includes('intern') || lower.includes('job'));
}
const m = $input.first().json || {};
const meta = m.metadata || {};
const from = addr(m.from || meta.from || m.fromAddress || '').toLowerCase();
const subject = String(m.subject || meta.subject || '').trim();
let body = String(m.textPlain || m.text || m.textAsHtml || '').trim();
if (!body && (m.html || m.textHtml)) {
  body = String(m.html || m.textHtml).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
if (!from) return [];
if (from === 'info@themobileprof.com') return [];
if (/mailer-daemon|no-?reply|postmaster/i.test(from)) return [];
if (/n8n smoke/i.test(subject)) return [];
if (!body) body = '(empty body)';
const hay = subject + ' ' + body;
if (looksLikeApplication(hay)) {
  const task_description = [
    'Parse and score this application against the open JD. Recommend shortlist or reject with reasons. Do not hire. Do not email.',
    '',
    'From: ' + from,
    'Subject: ' + (subject || '(no subject)'),
    '',
    body.slice(0, 8000)
  ].join('\n');
  return [{
    json: {
      department: 'hr',
      from,
      subject,
      task_description,
      context_data: {
        channel: 'email',
        department: 'hr',
        action: 'ingest',
        cannot_hire: true,
        cannot_send: true,
        from,
        subject,
        applicant_email: from
      }
    }
  }];
}
const task_description = [
  'Draft a short plain-text reply as TheMobileProf from info@themobileprof.com.',
  'Do not claim the email was sent. No markdown. Keep it under 250 words.',
  '',
  'From: ' + from,
  'Subject: ' + (subject || '(no subject)'),
  '',
  body.slice(0, 8000)
].join('\n');
return [{
  json: {
    department: 'growth',
    from,
    subject,
    task_description,
    context_data: {
      channel: 'email',
      department: 'growth',
      from,
      subject
    }
  }
}];

const worker = $input.first().json;
const prep = $('Prepare inbound').item.json;
let text = String(worker.output_text || 'Could not draft a reply.');
text = text.replace(/^#{1,6}\s+/gm, '').replace(/\*\*/g, '').replace(/\*/g, '').trim();
let subject = prep.subject || '(no subject)';
if (!/^re:\s/i.test(subject)) subject = 'Re: ' + subject;
return [{
  json: {
    action: 'store',
    to: prep.from,
    subject,
    text,
    from_original: prep.from,
    subject_original: prep.subject
  }
}];

const worker = $('Call growth').item.json;
const prep = $('Prepare inbound').item.json;
const sd = worker.structured_data || {};
let email = String(sd.email || prep.from || '').trim();
let name = String(sd.contact_name || sd.name || '').trim();
if (!name && email.includes('@')) name = email.split('@')[0];
return [{ json: {
  contact_name: name,
  email,
  phone: String(sd.phone || '').trim(),
  company_name: String(sd.company_name || '').trim(),
  pipeline_stage: String(sd.pipeline_stage || 'new'),
  notes: ('Inbound email: ' + (prep.subject || '')).slice(0, 500),
  source: 'email'
} }];

const prep = $('Prepare inbound').item.json;
let roles = [];
try {
  const fetched = $('Fetch HR roles').first().json || {};
  const all = fetched.roles || [];
  roles = all.filter((r) => String(r.status) === 'open').map((r) => ({
    id: r.id, slug: r.slug, title: r.title, kind: r.kind, jd: r.jd, project: r.project_name
  }));
} catch (e) {}
const context_data = Object.assign({}, prep.context_data || {}, { open_roles: roles });
return [{ json: Object.assign({}, prep, { context_data }) }];

const worker = $('Call HR').item.json;
const prep = $('Attach open roles').item.json;
const sd = worker.structured_data || {};
if (String(worker.status || '') !== 'success') return [];
const save = sd.save_application === true || sd.save_application === 'true';
const name = String(sd.applicant_name || sd.name || '').trim();
const email = String(sd.applicant_email || sd.email || prep.from || '').trim();
const cv = String(sd.cv_text || '').trim();
if (!save && !name && !cv) return [];
return [{ json: {
  structured_data: sd,
  source: 'email',
  role_slug: sd.role_slug || '',
  role_id: sd.role_id || 0,
  applicant_email: email
} }];
